	('ecbbe8de-bd61-4f83-8cde-fd6b047b7f95', NULL, '25b420e7-1544-5cfd-9f7f-dd81420b6693', NULL, 'create', 'site_content', '26f358b0-5b18-4872-aeb9-7f81911b412e', '{"new": {"id": "26f358b0-5b18-4872-aeb9-7f81911b412e", "access": "Tenant fobs grant access to their leased floor and shared amenities. Contact property management to add or remove credentials.", "parking": "Visitor parking is available on P2 and P3 with front desk validation. Monthly reserved spots available on request.", "site_id": "25b420e7-1544-5cfd-9f7f-dd81420b6693", "overview": "One Commerce Plaza is a 14-story Class A office tower in Uptown Charlotte with 24/7 concierge, a rooftop terrace, and on-site fitness center.", "policies": "Quiet hours in shared amenity spaces are 9:00 PM-7:00 AM. Pets are not permitted in common areas.", "deliveries": "All deliveries must be scheduled with the front desk 24 hours in advance and routed through the loading dock.", "front_desk": "Front desk is staffed Monday-Friday, 7:00 AM-7:00 PM. After-hours access requires a building fob.", "updated_at": "2026-10-17T15:26:19.517848+00:00", "updated_by": "5b7bced6-8e6d-50c8-8328-0d9598fdf883", "loading_dock": "Loading dock is on the south side of the building, accessible from Church Street. Hours: 6:00 AM-4:00 PM Monday-Friday.", "emergency_guidance": "In case of emergency, use the nearest stairwell - elevators are disabled during fire alarms. Assembly point is the plaza across South Tryon Street.", "security_procedures": "Building access requires a fob after 7:00 PM and on weekends. Visitors must be escorted past the lobby turnstiles."}}', NULL, NULL, '2026-10-17 15:26:19.517848+00'),
