INSERT INTO portfolio.site_content (id, site_id, overview, front_desk, emergency_guidance, parking, loading_dock, deliveries, security_procedures, access, policies, updated_at, updated_by) VALUES
	('26f358b0-5b18-4872-aeb9-7f81911b412e', '25b420e7-1544-5cfd-9f7f-dd81420b6693', 'One Commerce Plaza is a 14-story Class A office tower in Uptown Charlotte with 24/7 concierge, a rooftop terrace, and on-site fitness center.', 'Front desk is staffed Monday-Friday, 7:00 AM-7:00 PM. After-hours access requires a building fob.', 'In case of emergency, use the nearest stairwell - elevators are disabled during fire alarms. Assembly point is the plaza across South Tryon Street.', 'Visitor parking is available on P2 and P3 with front desk validation. Monthly reserved spots available on request.', 'Loading dock is on the south side of the building, accessible from Church Street. Hours: 6:00 AM-4:00 PM Monday-Friday.', 'All deliveries must be scheduled with the front desk 24 hours in advance and routed through the loading dock.', 'Building access requires a fob after 7:00 PM and on weekends. Visitors must be escorted past the lobby turnstiles.', 'Tenant fobs grant access to their leased floor and shared amenities. Contact property management to add or remove credentials.', 'Quiet hours in shared amenity spaces are 9:00 PM-7:00 AM. Pets are not permitted in common areas.', '2026-10-17 15:26:19.517848+00', '5b7bced6-8e6d-50c8-8328-0d9598fdf883');
INSERT INTO portfolio.site_faqs (id, site_id, question, answer, sort_order, created_at, updated_at) VALUES
	('83b92e33-38e4-4222-9a51-042e3610f209', '25b420e7-1544-5cfd-9f7f-dd81420b6693', 'What are the building hours?', 'The building is open Monday-Friday, 7:00 AM-7:00 PM. Tenants with fob access may enter 24/7.', 1, '2026-10-17 15:26:19.517848+00', '2026-10-17 15:26:19.517848+00'),
	('df565bcb-c957-48de-996f-95b003aaa8e0', '25b420e7-1544-5cfd-9f7f-dd81420b6693', 'How do I reserve a conference room?', 'Use the Reservations tab in the tenant portal to check availability and book Conference Center A.', 2, '2026-10-17 15:26:19.517848+00', '2026-10-17 15:26:19.517848+00'),
	('9ca44c0d-e0ef-4b0c-9c13-26070ebe910e', '25b420e7-1544-5cfd-9f7f-dd81420b6693', 'Who do I contact for a maintenance issue?', 'Submit a service request through the tenant portal and the building engineering team will be dispatched.', 3, '2026-10-17 15:26:19.517848+00', '2026-10-17 15:26:19.517848+00');
