-- =============================================================================
-- PlutusPM: full test-environment data seed (generated 2026-10-20 from local Supabase)
--
-- Contains every row from the app schemas (metrics, ops, platform, portfolio,
-- tenant, vendor, visitor) plus auth.users / auth.identities.
--
-- Prerequisite: the schema must already exist on the target project:
--     supabase link --project-ref <ref> && supabase db push
--
-- Apply:
--     psql "<remote connection string>" -v ON_ERROR_STOP=1 -f supabase/seed_test_env.sql
--   (or paste it into the Supabase SQL editor)
--
-- !! DESTRUCTIVE: TRUNCATES all app-schema tables before inserting, so the target
--    ends up identical to the test env (and seed rows from migrations don't conflict).
--    Do NOT run it against a project that holds real data.
--
-- Logins (password "password123"): demo@cre.local, manager2@cre.local,
--   tenant@cre.local, tenant2@cre.local, vendor@cre.local
-- =============================================================================

begin;

-- Skip triggers + FK checks during load (circular FKs: leases, assets,
-- visits<->passes, checklist_items, tenant_documents<->versions), and keep
-- audit/profile triggers from adding duplicate rows.
set local session_replication_role = replica;
set local search_path = '';
set local client_min_messages = warning;

